INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', 'Identifiers & registration', '[["The identifier combination","A business entity needs its TIN AND its business registration number, both. A Malaysian individual may use a MyKad number alone. The SST registration number is included where applicable, otherwise the literal NA."],["Registration","Log in through MyTax to reach the MyInvois Portal. API submitters additionally register their ERP in the portal to self-provision a client ID and secret, and need an organisation digital certificate from a Malaysian certification authority."],["Who accredits what","The tax authority accredits nothing — a taxpayer submitting by portal or direct API needs no approved vendor. Accreditation exists only on the Peppol route. \"MDEC-accredited software required\" is wrong for most submitters."],["Managed by","MDEC (Malaysia Digital Economy Corporation)"],["Used for","Cross-border and B2G invoice exchange"],["Format difference","MyInvois typically uses UBL 2.1 JSON; Peppol uses UBL 2.1 XML with PINT"]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Malaysia') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Identificadores y registro', '[["La combinación de identificadores","Una entidad mercantil necesita su TIN Y su número de registro mercantil, ambos. Un particular malasio puede usar solo el número de MyKad. El número de registro del SST se incluye cuando proceda; si no, el literal NA."],["Alta","Se accede por MyTax hasta el portal MyInvois. Quien envíe por API registra además su ERP en el portal para autoaprovisionarse un client ID y un secreto, y necesita un certificado digital de organización de una autoridad de certificación malasia."],["Quién acredita qué","La administración tributaria no acredita nada: quien envía por portal o API directa no necesita proveedor aprobado. La acreditación existe solo en la vía Peppol. «Se exige software acreditado por MDEC» es falso para la mayoría."],["Gestionado por","MDEC (Malaysia Digital Economy Corporation)"],["Se usa para","Intercambio de facturas transfronterizo y B2G"],["Diferencia de formato","MyInvois suele usar UBL 2.1 JSON; Peppol usa UBL 2.1 XML con PINT"]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Malaysia') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["Die Kennungskombination","Ein Unternehmen braucht seine TIN UND seine Handelsregisternummer, beides. Eine malaysische Privatperson kann allein die MyKad-Nummer verwenden. Die SST-Registrierungsnummer wird angegeben, wo einschlägig, sonst wörtlich NA."],["Registrierung","Anmeldung über MyTax zum MyInvois-Portal. Wer per API übermittelt, registriert zusätzlich sein ERP im Portal, um Client-ID und Secret selbst zu erzeugen, und braucht ein Organisationszertifikat einer malaysischen Zertifizierungsstelle."],["Wer was akkreditiert","Die Steuerbehörde akkreditiert nichts — wer über Portal oder direkte API übermittelt, braucht keinen zugelassenen Anbieter. Akkreditierung gibt es nur auf dem Peppol-Weg. «MDEC-akkreditierte Software erforderlich» ist für die meisten falsch."],["Verwaltet von","MDEC (Malaysia Digital Economy Corporation)"],["Verwendet für","Grenzüberschreitenden und B2G-Rechnungsaustausch"],["Formatunterschied","MyInvois nutzt typischerweise UBL 2.1 JSON; Peppol nutzt UBL 2.1 XML mit PINT"]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Malaysia') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["La combinaison d''identifiants","Une entité commerciale a besoin de son TIN ET de son numéro d''immatriculation, les deux. Un particulier malaisien peut n''utiliser que son numéro MyKad. Le numéro d''enregistrement SST figure le cas échéant, sinon la mention littérale NA."],["Inscription","On se connecte via MyTax pour atteindre le portail MyInvois. Qui transmet par API y enregistre en outre son ERP afin de s''auto-provisionner un client ID et un secret, et doit détenir un certificat numérique d''organisation d''une autorité de certification malaisienne."],["Qui agrée quoi","L''administration fiscale n''agrée rien : qui transmet par le portail ou l''API directe n''a besoin d''aucun éditeur approuvé. L''agrément n''existe que sur la voie Peppol. « Logiciel agréé MDEC requis » est faux pour la plupart."],["Géré par","MDEC (Malaysia Digital Economy Corporation)"],["Utilisé pour","L''échange de factures transfrontalier et B2G"],["Différence de format","MyInvois utilise généralement UBL 2.1 JSON ; Peppol utilise UBL 2.1 XML avec PINT"]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Malaysia') AND d.section = 'file_format' AND d.sort_order = 1;
