SELECT d.id, 'fr', 'Format et norme', '[["Syntaxe de base","UBL 2.1 (ISO/IEC 19845)"],["Modèle sémantique européen","EN 16931"],["Extension nationale (CIUS)","RO_CIUS 1.0.1"],["Base légale de la CIUS","Arrêté du ministère des Finances 1366/2021"]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Romania') AND d.section = 'file_format' AND d.sort_order = 0;
